UPDATE global_learning_items SET example_en='I have lived here since 2021.',metadata_json='{"rule": "since + starting point; for + duration", "common_mistake": "Do not use “for” before a starting point such as 2021.", "drill": "Choose the form that matches the rule.", "answer": "Use the rule shown above.", "examples": ["I have lived here since 2021.", "She has worked here for five years."], "drills": ["We have known each other ___ high school.", "He has worked here ___ three years."], "drill_answers": ["since", "for"], "quality_reviewed": true}',updated_at=NOW() WHERE external_key='grammar-lesson-001' AND is_active=1;
UPDATE global_learning_items SET example_en='The office opens at 8:30 every weekday.',metadata_json='{"rule": "Use for routines, facts, and schedules", "common_mistake": "Use the base/s form for routines; do not use -ing for a regular routine.", "drill": "Choose the form that matches the rule.", "answer": "Use the rule shown above.", "examples": ["The office opens at 8:30 every weekday.", "She checks customer requests every morning."], "drills": ["Our branch ___ at nine. (open/opens)", "He usually ___ by bus. (travel/travels)"], "drill_answers": ["opens", "travels"], "quality_reviewed": true}',updated_at=NOW() WHERE external_key='grammar-lesson-002' AND is_active=1;
UPDATE global_learning_items SET example_en='The team is discussing the proposal now.',metadata_json='{"rule": "Use for actions in progress or temporary situations", "common_mistake": "Use be + V-ing for an action happening now or a temporary situation.", "drill": "Choose the form that matches the rule.", "answer": "Use the rule shown above.", "examples": ["The team is discussing the proposal now.", "I am working from home this week."], "drills": ["They ___ the system at the moment. (test/are testing)", "She ___ with a client now. (speaks/is speaking)"], "drill_answers": ["are testing", "is speaking"], "quality_reviewed": true}',updated_at=NOW() WHERE external_key='grammar-lesson-003' AND is_active=1;
UPDATE global_learning_items SET example_en='The supplier delivered the order yesterday.',metadata_json='{"rule": "Use for completed past actions", "common_mistake": "Use a past form for a finished action at a finished past time.", "drill": "Choose the form that matches the rule.", "answer": "Use the rule shown above.", "examples": ["The supplier delivered the order yesterday.", "We discussed the budget last Friday."], "drills": ["The meeting ___ at 4 p.m. yesterday. (ends/ended)", "We ___ the email last night. (receive/received)"], "drill_answers": ["ended", "received"], "quality_reviewed": true}',updated_at=NOW() WHERE external_key='grammar-lesson-004' AND is_active=1;
UPDATE global_learning_items SET example_en='I was reviewing the contract when the client called.',metadata_json='{"rule": "Use for an action in progress at a past time", "common_mistake": "Do not omit was/were before the -ing form.", "drill": "Choose the form that matches the rule.", "answer": "Use the rule shown above.", "examples": ["I was reviewing the contract when the client called.", "They were waiting for the train at eight o’clock."], "drills": ["She ___ when the lights went out. (was presenting/presented)", "We ___ for the manager at noon. (were waiting/waited)"], "drill_answers": ["was presenting", "were waiting"], "quality_reviewed": true}',updated_at=NOW() WHERE external_key='grammar-lesson-005' AND is_active=1;
UPDATE global_learning_items SET example_en='The company has opened three new branches this year.',metadata_json='{"rule": "Connect past experience/action to the present", "common_mistake": "Do not normally use present perfect with a finished time such as “yesterday”.", "drill": "Choose the form that matches the rule.", "answer": "Use the rule shown above.", "examples": ["The company has opened three new branches this year.", "I have already sent the revised document."], "drills": ["She ___ just ___ the form. (has/submitted)", "They ___ here since May. (have worked/worked)"], "drill_answers": ["has submitted", "have worked"], "quality_reviewed": true}',updated_at=NOW() WHERE external_key='grammar-lesson-006' AND is_active=1;
UPDATE global_learning_items SET example_en='The train had left before we reached the station.',metadata_json='{"rule": "Show an action completed before another past action", "common_mistake": "Use had + past participle for the earlier of two past events when the sequence needs emphasis.", "drill": "Choose the form that matches the rule.", "answer": "Use the rule shown above.", "examples": ["The train had left before we reached the station.", "She had completed the report before the meeting began."], "drills": ["By the time I arrived, the shop ___. (had closed/closed)", "He ___ the file before he sent the email. (had checked/checked)"], "drill_answers": ["had closed", "had checked"], "quality_reviewed": true}',updated_at=NOW() WHERE external_key='grammar-lesson-007' AND is_active=1;
UPDATE global_learning_items SET example_en='I think sales will improve next quarter.',metadata_json='{"rule": "Use for predictions, decisions, and offers", "common_mistake": "Use will + base verb; do not add “to” after will.", "drill": "Choose the form that matches the rule.", "answer": "Use the rule shown above.", "examples": ["I think sales will improve next quarter.", "I will send you the updated schedule this afternoon."], "drills": ["I think the meeting ___ on time. (will start/will starts)", "I ___ you with the boxes. (will help/am help)"], "drill_answers": ["will start", "will help"], "quality_reviewed": true}',updated_at=NOW() WHERE external_key='grammar-lesson-008' AND is_active=1;
