UPDATE global_learning_items SET example_en='I called the supplier because the order was late.',metadata_json='{"rule": "Connect clauses and logical relationships", "common_mistake": "Choose a conjunction that expresses the intended logical relationship between clauses.", "drill": "Choose the form that matches the rule.", "answer": "Use the rule shown above.", "examples": ["I called the supplier because the order was late.", "The room is small, but it is well equipped."], "drills": ["We stayed inside ___ it was raining. (because/although)", "The price is high, ___ demand remains strong. (but/so)"], "drill_answers": ["because", "but"], "quality_reviewed": true}',updated_at=NOW() WHERE external_key='grammar-lesson-050' AND is_active=1;
